cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t=>t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ':', info.map(c => c.name + ' (' + c.type + ')'));
  const count = db.prepare('SELECT count(*) as c FROM ' + t.name).get();
  console.log('  rows:', count.c);
}
"

cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Check what flights exist from LOS or to LHR
const flights = db.prepare(\"SELECT * FROM flights WHERE source_skill = 'tau2Airline'\").all();
console.log('All tau2Airline flights:');
flights.forEach(f => {
  console.log(JSON.stringify({
    flight_id: f.flight_id,
    origin: f.origin,
    destination: f.destination,
    departure: f.departure_time,
    arrival: f.arrival_time,
    status: f.status,
    stops: f.stops,
    cabin_prices: f.cabin_prices_json,
    dates: f.dates_json
  }));
});
"

