cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Search parameters
const origin = 'LOS';
const destination = 'LHR';
const date = '2026-09-09';
const cabin = 'economy';

// Get all distinct origins in the DB
const allOrigins = db.prepare('SELECT DISTINCT origin FROM flights').all().map(r => r.origin);
const allDests = db.prepare('SELECT DISTINCT destination FROM flights').all().map(r => r.destination);

// Check direct flights from LOS
const directFromLOS = db.prepare(\"SELECT * FROM flights WHERE origin = 'LOS'\").all();

// Check flights to LHR
const toLHR = db.prepare(\"SELECT * FROM flights WHERE destination = 'LHR'\").all();

// For one-stop: need LOS -> X and X -> LHR, both available on that date
// But LOS is not an origin in the database at all.

const result = {
  search_parameters: {
    origin: origin + ' (Lagos)',
    destination: destination + ' (London Heathrow)',
    date: date,
    cabin_class: cabin,
    flight_type: 'one_stop'
  },
  search_timestamp: new Date().toISOString(),
  results: {
    onestop_flights_found: 0,
    details: [],
    note: 'No one-stop (connecting) flights found for the route LOS (Lagos) → LHR (London Heathrow) on ' + date + ' in economy class.'
  },
  diagnostics: {
    flights_from_LOS: directFromLOS.length,
    flights_to_LHR: toLHR.map(f => {
      const dates = JSON.parse(f.dates_json);
      const dateInfo = dates[date] || null;
      return {
        flight_id: f.flight_id,
        route: f.origin + ' → ' + f.destination,
        available_dates: Object.keys(dates),
        available_on_requested_date: !!dateInfo,
        economy_price: dateInfo ? (dateInfo.prices ? dateInfo.prices.economy : null) : null,
        source_skill: f.source_skill
      };
    }),
    available_origins_in_database: allOrigins.sort(),
    available_destinations_in_database: allDests.sort(),
    explanation: 'The airline database contains no flights departing from LOS (Lagos). The only flights arriving at LHR (London Heathrow) depart from JFK, and none are available on the requested date of ' + date + '. The closest JFK→LHR flight dates are 2026-09-10 and 2026-09-20. A one-stop LOS→LHR itinerary cannot be constructed from the current inventory.'
  }
};

const json = JSON.stringify(result, null, 2);
require('fs').writeFileSync('/workspace/onestop_flight_results_Q3review.json', json);
console.log(json);
console.log('\n✅ File saved to /workspace/onestop_flight_results_Q3review.json');
"
